export function validatePlanStructure(tasks,manifest,mapping){
 assert.equal(tasks.length,32);assert.equal(tasks.flatMap(t=>t.subtasks).length,97);
 assert.equal(manifest.planId,PLAN);assert.equal(manifest.tag,TAG);
 const taskIds=new Set(ids(tasks.map(t=>t.id)));assert.equal(taskIds.size,tasks.length);
 const graph=new Map(),childIds=new Set();
 for(const t of tasks){
  assert.match(String(t.id),/^[1-9]\d*$/);assert.ok(t.title&&t.description&&t.details&&t.testStrategy);
  assert.ok(['high','medium','low'].includes(t.priority));
  assert.equal(t.status,[25,26,30].includes(Number(t.id))?'deferred':'pending');
  assert.equal(new Set(ids(t.dependencies)).size,t.dependencies.length);
  for(const d of t.dependencies)assert.ok(taskIds.has(String(d))&&String(d)!==String(t.id));
  graph.set(String(t.id),ids(t.dependencies));
  const local=new Set(ids(t.subtasks.map(c=>c.id)));assert.equal(local.size,t.subtasks.length);
  for(const c of t.subtasks){
   const full=t.id+'.'+c.id;childIds.add(full);assert.ok(c.title&&c.description&&c.details);
   assert.equal(c.status,t.status);if(c.parentTaskId!==undefined)assert.equal(String(c.parentTaskId),String(t.id));
   const deps=c.dependencies.map(d=>String(d).includes('.')?String(d):t.id+'.'+d);
   assert.ok(!deps.includes(full));graph.set(full,[...ids(t.dependencies),...deps]);
  }
 }
 const visited=new Set();function visit(id,active=new Set()){
  assert.ok(graph.has(id),'missing dependency '+id);assert.ok(!active.has(id),'cycle '+id);if(visited.has(id))return;
  for(const dep of graph.get(id))visit(dep,new Set([...active,id]));visited.add(id);
 }for(const id of graph.keys())visit(id);
 for(const [key,count,prefix]of [['macroGoals',5,'G'],['microGoals',13,'M']]){
  assert.equal(mapping[key].length,count);
  for(let n=1;n<=count;n++){
   const id=prefix+(prefix==='M'?String(n).padStart(2,'0'):n),r=mapping[key].find(x=>x.id===id);assert.ok(r,id);
   assert.ok(r.tasks.some(x=>![1,32].includes(Number(x))),id+' needs substantive work');
   for(const i of r.tasks)assert.ok(taskIds.has(String(i)));for(const s of r.subtasks)assert.ok(childIds.has(s));
  }
 }
 assert.equal(mapping.historicalProblemGroups.length,30);
 for(const h of mapping.historicalProblemGroups){
  assert.ok(h.evidenceLevel&&h.currentDisposition&&h.sources.length);
  assert.ok(h.taskIds.some(x=>![1,32].includes(Number(x))),h.id+' only bookkeeping');
  for(const i of h.taskIds)assert.ok(taskIds.has(String(i)));for(const s of h.subtaskIds)assert.ok(childIds.has(s));
 }
 const waves=new Map(manifest.executionWaves.flatMap(w=>w.taskIds.map(id=>[String(id),w.wave])));
 assert.equal(waves.size,tasks.length);
 for(const t of tasks){
  const entry=manifest.tasks.find(x=>String(x.id)===String(t.id));assert.equal(entry.subtaskCount,t.subtasks.length);
  assert.equal(entry.executionWave,waves.get(String(t.id)));assert.ok([1,2].includes(entry.phase));
  for(const d of t.dependencies)assert.ok(waves.get(String(d))<waves.get(String(t.id)),'wave ordering');
 }
 for(const g of manifest.gates)for(const id of g.tasks)assert.ok(taskIds.has(String(id)));
 assert.equal(manifest.executionStarted,false);assert.equal(manifest.authorization.planningApproved,true);
 for(const field of ['implementationApproved','paidEvaluationApproved','deploymentIncludedAndApproved','externalPublicationApproved','githubCommitPushPrApproved','productionQaWritesApproved'])assert.equal(manifest.authorization[field],false,field);
 assert.equal(manifest.authorization.newPaidEvaluationMaxUsdBeforeTax,0);assert.equal(manifest.authorization.newEvaluationUsedUsdBeforeTax,0);
 const e=manifest.evaluationDesign;assert.equal(e.maxTotalRequests,e.maxGenerationRequests+e.maxMainJudgeRequests+e.maxCalibrationRequests);
 assert.equal(e.maxTotalRequests,756);assert.equal(e.newCases,60);assert.equal(e.word+e.grammar,60);assert.equal(Object.values(e.strata).reduce((a,b)=>a+b),60);
 assert.equal(e.financialLimitUsd,null);assert.equal(e.quality.candidateVisibleCompletedPerModel,60);assert.equal(e.quality.candidateUnmeasured,0);
 assert.equal(e.quality.criticalErrors,0);assert.equal(e.quality.pairedRegressions,0);assert.equal(e.quality.requiredValidCorrectionRejections,0);
 assert.equal(e.rawAndVisibleSeparated,true);
 return {parents:tasks.length,subtasks:childIds.size,nodes:graph.size,macroGoals:5,microGoals:13,historyGroups:30};
}

try{
 const source=await json(resolve(SOURCE,'.taskmaster/tasks/tasks.json')),root=await json(resolve(ROOT,'.taskmaster/tasks/tasks.json'));
 const mapping=await json(resolve(SOURCE,`.taskmaster/docs/${TAG}-mapping.json`));
 const summary=validatePlanStructure(source[TAG].tasks,m,mapping);assert.deepEqual(source[TAG],root[TAG]);
 pass('32parents/97children;5macro/13micro/30history including substantive mappings;DAG/waves/status/authorization/cost constraints');
 const mutations=[
  ['cycle',d=>{d.tasks[0].dependencies=[2];}],
  ['missing dependency',d=>{d.tasks[0].dependencies=[999];}],
  ['missing micro goal',d=>{d.mapping.microGoals.pop();}],
  ['false done',d=>{d.tasks[0].status='done';}],
  ['old authorization reuse',d=>{d.manifest.authorization.paidEvaluationApproved=true;}],
  ['reduced denominator',d=>{d.manifest.evaluationDesign.newCases=30;}],
  ['hidden transport incompleteness',d=>{d.manifest.evaluationDesign.quality.candidateVisibleCompletedPerModel=59;}],
  ['unmapped history',d=>{d.mapping.historicalProblemGroups[0].taskIds=[1,32];}],
 ];
 for(const [name,mutate]of mutations){const d=structuredClone({tasks:source[TAG].tasks,manifest:m,mapping});mutate(d);assert.throws(()=>validatePlanStructure(d.tasks,d.manifest,d.mapping),undefined,name);}
 pass('eight negative controls reject cycles/missing mappings/false completion/approval reuse/reduced scope');
 const b=await json(resolve(OUT,'baseline.json'));
 for(const [label,base,doc]of [['source',SOURCE,source],['root',ROOT,root]]){
  for(const [tag,old]of Object.entries(b.locations[label].tags))assert.deepEqual(doc[tag],old,label+'/'+tag);
  for(const [p,h]of Object.entries(b.locations[label].manifestHashes))assert.equal(await hash(resolve(base,p)),h,p);
  const registry=await json(resolve(base,'.taskmaster/docs/dashboard-plans.json'));
  assert.equal(registry.defaultPlanId,PLAN);assert.equal(registry.plans.length,5);
  for(const entry of b.locations[label].registry.plans){const now=registry.plans.find(x=>x.id===entry.id);assert.ok(now);if(entry.id==='comprehensive-remediation-2026-11-05')assert.equal(now.kind,'previous');else assert.deepEqual(now,entry);}
 }
 pass('old four tag objects and manifests exactly preserved; five-plan registry retains separate histories and budgets');
 const expected=(await json(resolve(OUT,'registration-payload.json'))).tasks;
 for(const t of source[TAG].tasks){const e=expected.find(x=>String(x.id)===String(t.id));
  for(const k of ['title','description','details','testStrategy','priority','status'])assert.equal(t[k],e[k],t.id+'/'+k);
  assert.deepEqual(ids(t.dependencies),ids(e.dependencies));
  for(const c of t.subtasks){const ec=e.subtasks.find(x=>String(x.id)===String(c.id));for(const k of ['title','description','details','status'])assert.equal(c[k],ec[k],t.id+'.'+c.id+'/'+k);assert.deepEqual(ids(c.dependencies),ids(ec.dependencies));}
  const line=t.details.split('\n').find(x=>x.startsWith('관련 경계: '));
  for(const rel of line.slice('관련 경계: '.length).split(', '))assert.ok((await stat(resolve(rel.startsWith('ROOT:')?ROOT:SOURCE,rel.replace(/^ROOT:/,'')))).isFile(),rel);
 }
 const mcp=await json(resolve(OUT,'mcp-requery.json'));assert.equal(mcp.getTasks.data.tasks.length,32);assert.equal(mcp.nextTask.data.nextTask.id,1);
 const cli=await readFile(resolve(OUT,'cli-04-validate-dependencies.log'),'utf8');assert.match(cli,/No invalid dependencies/);assert.match(cli,/126/);
 const corrected=await json(resolve(OUT,'cli-workflow-corrected.json'));assert.ok(corrected.commands.every(x=>x.exitCode===0));
 for(const cmd of corrected.commands)assert.equal(await hash(resolve(OUT,cmd.log)),cmd.sha256);
 pass('official manual MCP content matches complete task spec; actual requery/next1; CLI126dependencies/generate/next exit0');
 const allowed=new Set(['README.md','.taskmaster/README.md','.taskmaster/tasks/tasks.json','.taskmaster/docs/dashboard-plans.json','.taskmaster/scripts/test-comprehensive-remediation-dashboard.mjs','.taskmaster/scripts/test-multi-plan-dashboard.mjs']);
 for(const [p,h]of Object.entries(b.source.hashes))if(!allowed.has(p))assert.equal(await hash(resolve(SOURCE,p)),h,p);
 assert.equal(git(SOURCE,'rev-parse','HEAD'),b.source.head);assert.equal(git(SOURCE,'branch','--show-current'),b.source.branch);
 assert.equal(git(ROOT,'rev-parse','HEAD'),b.root.head);assert.equal(git(ROOT,'branch','--show-current'),b.root.branch);
 assert.equal(git(SOURCE,'diff','--cached','--name-only'),'');assert.equal(git(ROOT,'diff','--cached','--name-only'),'');
 const audit=await json(resolve(ROOT,'outputs/comprehensive-defect-audit-20261105/baseline.json'));
 const impl=await json(resolve(ROOT,'outputs/comprehensive-remediation-implementation-20261105/baseline.json'));
 for(const block of [audit.rootSourceHashes,audit.oldEvidenceHashes,audit.sealedEvaluationHashes,impl.frozenEvidenceHashes])for(const [p,h]of Object.entries(block))assert.equal(await hash(resolve(ROOT,p)),h,p);
 for(const [p,h]of Object.entries(b.historicalJsonHashes))assert.equal(await hash(resolve(p.startsWith('SOURCE:')?SOURCE:ROOT,p.replace(/^SOURCE:/,''))),h,p);
 const historicalSource=resolve(ROOT,'work/comprehensive-defect-audit-20261105');
 assert.equal(git(historicalSource,'rev-parse','HEAD'),'5dd3067a70142e829dc366751a408e250f76122e');assert.equal(git(historicalSource,'status','--porcelain'),'');
 const readiness=await json(resolve(SOURCE,'docs/releases/2026-11-05-comprehensive-remediation-readiness.json'));
 // SOURCE in this frozen historical receipt names its original audit checkout,
 // not the new planning checkout where the receipt is also present in Git.
 for(const [p,item]of Object.entries(readiness.evidence))assert.equal(await hash(resolve(p.startsWith('SOURCE:')?historicalSource:ROOT,p.replace(/^(?:ROOT|SOURCE):/,''))),item.sha256,p);
 const published=await json(resolve(ROOT,'outputs/pr58-rollout-20261106/archive-source-verification.json'));
 assert.equal(await hash(resolve(ROOT,'outputs/pr58-rollout-20261106/site-qualified.tar.gz')),published.archiveSha256);
 const prior=await json(resolve(ROOT,'outputs/pr58-rollout-20261106/baseline.json'));
 assert.equal(await hash(resolve(ROOT,'outputs/comprehensive-remediation-publication-20261105/site-qualified.tar.gz')),prior.oldArchiveSha256);
 pass('runtime/build inputs/branches/HEAD/index preserved;ROOTproduct637/audit2089/prepublish251/247historicalJSON/v146-v147archives unchanged');
 for(const p of [m.planFile,m.prdFile,m.mappingFile,m.complexityFile,m.officialSourcesFile,`.taskmaster/docs/${TAG}-manifest.json`])assert.equal(await hash(resolve(ROOT,p)),await hash(resolve(SOURCE,p)),p);
 const official=await json(resolve(SOURCE,m.officialSourcesFile));assert.equal(official.installedVersion,'0.43.1');
 for(const s of official.sources)assert.equal(await hash(resolve(ROOT,s.localEvidence)),s.sha256,s.path);
 const prd=await readFile(resolve(SOURCE,m.prdFile),'utf8');for(const section of ['overview','functional-decomposition','structural-decomposition','dependency-graph','implementation-roadmap','test-strategy','architecture','risks','appendix'])assert.ok(prd.includes('<'+section+'>')&&prd.includes('</'+section+'>'),section);
 assert.equal((prd.match(/^### Capability:/gm)||[]).length,32);assert.equal((prd.match(/^#### Feature:/gm)||[]).length,97);
 assert.match(prd,/Existing public interfaces/);assert.match(prd,/Entry Criteria/);assert.match(prd,/Exit Criteria/);
 const generated=(await readdir(resolve(SOURCE,'.taskmaster/tasks'))).filter(x=>/^task_\d+_ai-quality-v147\.md$/.test(x));assert.equal(generated.length,32);
 for(const file of generated)assert.equal(await hash(resolve(SOURCE,'.taskmaster/tasks',file)),await hash(resolve(ROOT,'.taskmaster/tasks',file)));
 const management=await json(resolve(OUT,'management-update.json'));
 for(const item of management){const base=item.location==='source'?SOURCE:ROOT;const before=await readFile(resolve(OUT,'before',item.location,item.path)),now=await readFile(resolve(base,item.path));assert.ok(now.subarray(now.length-before.length).equals(before),item.path);}
 pass('official source hashes/RPG9sections/32capabilities/97features/public interfaces/generated32task docs match; historical management bytes retained');
 const health=await(await fetch('http://127.0.0.1:4318/api/health')).json();assert.equal(health.projectKey,createHash('sha256').update(ROOT).digest('hex').slice(0,20));
 const live=await(await fetch('http://127.0.0.1:4318/api/tasks')).json();assert.equal(live.plan.id,PLAN);assert.equal(live.tasks.length,32);assert.equal(live.tasks.flatMap(x=>x.subtasks).length,97);assert.equal(live.catalog.plans.length,5);
 assert.ok(live.tasks.every(t=>t.status!=='done'));assert.match(live.plan.budget,/US\$0/);assert.equal(live.plan.gates.find(x=>x.id==='AQ-G3').result.status,'held');
 pass('actual ROOT4318 identity/default new plan/32-97-zero implementation/five histories/approval-held gates');
 if(process.argv.includes('--final')){
  assert.equal(m.planningStatus,'complete');assert.equal(m.gates.find(x=>x.id==='AQ-P').result.status,'passed');
  for(const name of ['dashboard/results.json','historical-comprehensive/results.json','historical-multi/results.json'])assert.equal((await json(resolve(OUT,name))).passed,true,name);
  const validation=await json(resolve(SOURCE,m.validationFile));assert.equal(validation.status,'planning-complete');assert.equal(validation.implementationStarted,false);
  const display=await json(resolve(OUT,'final-display.json'));assert.equal(display.passed,true);assert.equal(display.checks.length,2);assert.ok(display.checks.every(x=>x.passed&&x.planGatePassed&&x.liveAndBothStaticCopies));
  const policy=await json(resolve(OUT,'policy-final-result.json'));assert.equal(policy.exitCode,0);assert.equal(policy.tests,2);assert.equal(policy.passed,2);assert.equal(policy.failed,0);
  for(const name of ['final-display.json','policy-final.log','policy-final-result.json'])assert.ok(Object.hasOwn(validation.evidenceSha256,name),name+' final evidence missing');
  for(const [p,h]of Object.entries(validation.evidenceSha256))assert.equal(await hash(resolve(OUT,p)),h,p);
  pass('final planning state/three dashboard regressions/validation evidence hashes verified; implementation remains unstarted');
 }
}catch(error){checks.push({name:error.message,passed:false});console.error(error);process.exitCode=1;}
finally{
 await mkdir(OUT,{recursive:true});const result={at:new Date().toISOString(),passed:checks.every(x=>x.passed),exitCode:process.exitCode||0,checks,scope:'Planning and local dashboard only; no product implementation, paid AI, deployment or production learner QA.'};
 await writeFile(resolve(OUT,process.argv.includes('--final')?'verification-final.json':'verification-structure.json'),JSON.stringify(result,null,2)+'\n');
}
